      Subroutine S04_SlabCF_NPP1_001 ( m, Rrup, ztor, specT, lnY, sigma, iflag )                 
                                                                                                                                    
      implicit none                                                                                                                 
                                                                                                                                    
      integer MAXPER                                                                                                                
      parameter (MAXPER= 20)
      REAL Period(MAXPER), a1(MAXPER), a2(MAXPER), a3(MAXPER),  a11(MAXPER), dsi(MAXPER)                                            
      REAL a4(MAXPER), a5(MAXPER), a6(MAXPER), c4(MAXPER), a9(MAXPER), a13(MAXPER), a4a(MAXPER)                                                  
      real Mref(MAXPER), Rrup, Ztor                                                                                                 
      REAL M, specT, sigma, fmag                                                                                                         
      REAL period2, lnY, period1, a1T, a2T, a3T, a4T, a5T, a6T, a4aT                                                                      
