     1      -0.0012613526, -0.0015349411, -6.3037646e-05, -0.00049641618, -0.00024960933, -0.0001911519, -0.00051925878,
     1      -0.00023652103, -0.0010016677, -0.00091860299, -0.0019393985, -0.0027910154, -0.0022060108/
      Data Mref(1:20) / 7.2703504, 7.2703504, 7.3667386, 7.8139098, 7.1788074, 7.3368526, 7.3729439, 7.1345005, 7.4796249,
     1      7.2179033, 7.284408, 7.8921147, 6.6902076, 7.5079304, 6.9723544, 7.1130766, 6.9096941, 7.1017958, 7.1200356, 7.2220531/
      Data dsi(1:20) / 88.444666, 88.444666, 113.7466, 231.23134, 128.65105, 131.06225, 143.61679, 244.89093, 104.06211, 76.264824,
     1      70.701959, 74.366028, 68.413529, 49.935933, 93.887285, 77.694362, 156.46634, 105.48652, 42.191566, 100.5695/
 
                                                                                                                                    
C Find the requested spectral period and corresponding coefficients                                                                 
      nPer =    20
C First check for the PGA case (i.e., specT=0.0)                                                                                    
      if (specT .eq. 0.0) then                                                                                                      
         period1  = period(1)                                                                                                       
         a1T   = a1(1)                                                                                                              
         a2T   = a2(1)                                                                                                              
         a3T   = a3(1)                                                                                                              
         a4T   = a4(1)                                                                                                              
         a5T   = a5(1)                                                                                                              
         a6T   = a6(1)                                                                                                              
         a11T  = a11(1)                                                                                                             
         dsiT  = dsi(1)                                                                                                             
         MrefT = Mref(1)                                                                                                            
         goto 1011                                                                                                                  
      elseif (specT .gt. 0.0) then                                                                                                  
C Now loop over the spectral period range of the attenuation relationship.                                                          
         do i=2,nper-1                                                                                                              
            if (specT .ge. period(i) .and. specT .le. period(i+1) ) then                                                            
               count1 = i                                                                                                           
               count2 = i+1                                                                                                         
               goto 1020                                                                                                            
            endif                                                                                                                   
         enddo                                                                                                                      
      endif                                                                                                                         
                                                                                                                                    
C Selected spectral period is outside range defined by attenuaton model.                                                            
      write (*,*)                                                                                                                   
      write (*,*) 'Sub-Inter Common Model001 Horizontal'
      write (*,*) 'attenuation model is not defined for a '                                                                         
      write (*,*) ' spectral period of: '                                                                                           
      write (*,'(a10,f10.5)') ' Period = ',specT                                                                                    
      write (*,*) 'This spectral period is outside the defined'                                                                     
      write (*,*) 'period range in the code or beyond the range'                                                                    
      write (*,*) 'of spectral periods for interpolation.'                                                                          
      write (*,*) 'Please check the input file.'                                                                                    
      write (*,*)                                                                                                                   
      stop 99                                                                                                                       
                                                                                                                                    
C Interpolate the coefficients for the requested spectral period.                                                                   
 1020 call S24_interp (period(count1),period(count2),a1(count1),a1(count2),                                                         
     +                 specT, a1T  ,iflag)                                                                                          
      call S24_interp (period(count1),period(count2),a2(count1),a2(count2),                                                         
     +                 specT, a2T  ,iflag)                                                                                          
      call S24_interp (period(count1),period(count2),a3(count1),a3(count2),                                                         
     +                 specT, a3T  ,iflag)                                                                                          
      call S24_interp (period(count1),period(count2),a4(count1),a4(count2),                                                         
     +                 specT, a4T  ,iflag)                                                                                          
      call S24_interp (period(count1),period(count2),a5(count1),a5(count2),                                                         
     +                 specT, a5T  ,iflag)                                                                                          
      call S24_interp (period(count1),period(count2),a6(count1),a6(count2),                                                         
     +                 specT, a6T  ,iflag)                                                                                          
      call S24_interp (period(count1),period(count2),a11(count1),a11(count2),                                                       
     +                 specT, a11T ,iflag)                                                                                          
      call S24_interp (period(count1),period(count2),dsi(count1),dsi(count2),                                                       
     +                 specT, dsiT ,iflag)                                                                                          
      call S24_interp (period(count1),period(count2),Mref(count1),Mref(count2),                                                     
     +                 specT, MrefT,iflag)                                                                                          
                                                                                                                                    
 1011 period1 = specT                                                                                                               
                                                                                                                                    
C     Set Constant Terms                                                                                                            
                                                                                                                                    
C     Compute the ground motion for the given spectral period.                                                                      
      if (M .le. MrefT) then 
         fmag = a4T*(M-MrefT)                                                   
      elseif(M .gt. MrefT) then                                                                                                                            
         fmag = a5T*(M-MrefT)                                                     
      endif                                                                                                                         
         lnY = a1T + ( a2T + a3T *(M-7.8))*alog(Rrup + 10.0*exp(0.4*(M-6.0)))                                            
     1         + fmag  + a11T*min(Ztor,dsiT) + a6T*Rrup             
                                                                                                                                 
      sigma = 0.65                                                                                                                  
                                                                                                                                    
c     Convert from g to gal                                                                                                         
      lnY = lnY + 6.89                                                                                                              
                                                                                                                                    
      period2 = period1                                                                                                             
                                                                                                                                    
      return                                                                                                                        
      end


