     +                 specT, dsiT ,iflag)                                                                                          
      call S24_interp (period(count1),period(count2),Mref(count1),Mref(count2),                                                     
     +                 specT, MrefT,iflag)                                                                                          
                                                                                                                                    
 1011 period1 = specT                                                                                                               
                                                                                                                                    
C     Set Constant Terms                                                                                                            
                                                                                                                                    
C     Compute the ground motion for the given spectral period.                                                                      
      if (M .le. MrefT) then 
         fmag = a4T*(M-MrefT)                                                   
      elseif(M .gt. MrefT) then                                                                                                                            
         fmag = a5T*(M-MrefT)                                                     
      endif                                                                                                                         
         lnY = a1T + ( a2T + a3T *(M-7.8))*alog(Rrup + 10.0*exp(0.4*(M-6.0)))                                            
     1         + fmag  + a11T*min(Ztor,dsiT) + a6T*Rrup             
                                                                                                                                 
      sigma = 0.65                                                                                                                  
                                                                                                                                    
c     Convert from g to gal                                                                                                         
      lnY = lnY + 6.89                                                                                                              
                                                                                                                                    
      period2 = period1                                                                                                             
                                                                                                                                    
      return                                                                                                                        
      end


