      Subroutine S04_SlabCF_NPP4_017 ( m, Rrup, ztor, specT, lnY, sigma, iflag )                 
                                                                                                                                    
      implicit none                                                                                                                 
                                                                                                                                    
      integer MAXPER                                                                                                                
      parameter (MAXPER= 20)
      REAL Period(MAXPER), a1(MAXPER), a2(MAXPER), a3(MAXPER),  a11(MAXPER), dsi(MAXPER)                                            
      REAL a4(MAXPER), a5(MAXPER), a6(MAXPER), c4(MAXPER), a9(MAXPER), a13(MAXPER), a4a(MAXPER)                                                  
      real Mref(MAXPER), Rrup, Ztor                                                                                                 
      REAL M, specT, sigma, fmag                                                                                                         
      REAL period2, lnY, period1, a1T, a2T, a3T, a4T, a5T, a6T, a4aT                                                                      
      REAL c4T, a9T, MrefT, dsiT, a11T, a13T                                                                                        
      integer iflag, count1, count2, nPer, i                                                                                        
                                                                                                                                    
      data period /   0.0000,   0.0100,   0.0200,   0.0300,   0.0500,   0.0750,   0.1000,   0.1500, 
     1                0.2000,   0.2500,   0.3000,   0.4000,   0.5000,   0.7500,   1.0000,   1.5000, 
     1                2.0000,   3.0000,   4.0000,   5.0000 / 
 
 
      Data a1(1:20) / 4.8939692, 4.8939692, 4.781872, 4.2419031, 4.6559781, 4.5741842, 6.3594883, 5.9718433, 5.6848394, 5.2215074,
     1      4.1148801, 5.3067963, 3.4242204, 1.7128611, 0.40902869, 0.48979701, 0.75410115, -0.020012859, -1.0447949, -1.1432411/
      Data a2(1:20) / -1.5438411, -1.5438411, -1.6342309, -1.5168508, -1.6451156, -1.620269, -1.8138688, -1.7810653, -1.6514079,
     1      -1.6014778, -1.3751392, -1.6534056, -1.2478134, -0.94945894, -0.82544098, -0.9349189, -0.93174096, -0.8811026,
     1      -0.79797663, -0.81230378/
      Data a3(1:20) / 0.049768902, 0.049768902, 0.037818166, 0.07181782, 0.12215693, 0.13799723, 0.053198829, 0.076868112,
     1      0.049973231, 0.0103675, 0.11983746, 0.022128268, 0.066183049, 0.12235593, 0.15949371, 0.1166721, 0.089430583,
     1      0.10497246, 0.10152793, 0.11263446/
      Data a4(1:20) / 0.81538568, 0.81538568, 0.91819888, 0.82326755, 0.76127036, 0.52414886, 0.95294199, 0.79446341, 0.75168998,
     1      0.9606494, 0.79265039, 1.1707922, 0.87377503, 0.96260475, 0.72635683, 1.181314, 1.6995962, 1.3164435, 1.2057185,
     1      1.5509816/
      Data a5(1:20) / 0.29362422, 0.29362422, 0.54032827, 0.37521613, 0.20339045, 0.07801915, 0.11145144, 0.44752431, 0.69694527,
     1      0.89516083, 0.25454961, 0.77150746, 0.60690321, 0.087505839, 0.22129139, 0.60850088, 0.3647473, 0.46680148, 0.6535735,
     1      0.46680933/
      Data a11(1:20) / 0.0049663732, 0.0049663732, 0.010950661, 0.0088812974, 0.018501467, 0.019478798, 0.011594148, 0.015063996,
     1      0.0070409084, 0.0071181897, 0.014619893, 0.0072234993, 0.012301011, 0.020418186, 0.023786757, 0.0099659444,
     1      0.010843039, 0.0070226502, 0.0062636642, 0.0034240124/
      Data a6(1:20) / -0.001011396, -0.001011396, -0.0010477795, -0.0010492982, -0.00021751489, -0.00088740525, -0.00047087658,
     1      -0.0010272365, -0.0011303996, -0.0020928301, -0.00078415991, -0.00035216184, -0.00063464413, -0.0023386009,
     1      -0.0029051793, -0.0017162252, -0.001759263, -0.0017604001, -0.0023632199, -0.0017092194/
      Data Mref(1:20) / 7.4549131, 7.4549131, 7.3757627, 7.0657533, 7.6012241, 7.5985928, 7.3994574, 7.3369248, 7.3035258,
     1      7.0733776, 7.4569089, 7.1138077, 7.6788754, 7.6496955, 7.446799, 6.9474024, 7.5001091, 7.4485109, 7.193268, 7.1794023/
      Data dsi(1:20) / 166.56498, 166.56498, 110.24629, 163.22588, 88.842461, 116.16031, 90.051349, 97.006157, 188.01257, 191.3096,
     1      89.796422, 155.62494, 92.847951, 65.705912, 68.362062, 111.61729, 80.843833, 86.973273, 88.592558, 141.05988/
 
                                                                                                                                    
C Find the requested spectral period and corresponding coefficients                                                                 
      nPer =    20
C First check for the PGA case (i.e., specT=0.0)                                                                                    
      if (specT .eq. 0.0) then                                                                                                      
         period1  = period(1)                                                                                                       
         a1T   = a1(1)                                                                                                              
         a2T   = a2(1)                                                                                                              
         a3T   = a3(1)                                                                                                              
         a4T   = a4(1)                                                                                                              
         a5T   = a5(1)                                                                                                              
         a6T   = a6(1)                                                                                                              
         a11T  = a11(1)                                                                                                             
         dsiT  = dsi(1)                                                                                                             
         MrefT = Mref(1)                                                                                                            
         goto 1011                                                                                                                  
      elseif (specT .gt. 0.0) then                                                                                                  
C Now loop over the spectral period range of the attenuation relationship.                                                          
         do i=2,nper-1                                                                                                              
            if (specT .ge. period(i) .and. specT .le. period(i+1) ) then                                                            
               count1 = i                                                                                                           
               count2 = i+1                                                                                                         
               goto 1020                                                                                                            
            endif                                                                                                                   
         enddo                                                                                                                      
      endif                                                                                                                         
                                                                                                                                    
C Selected spectral period is outside range defined by attenuaton model.                                                            
      write (*,*)                                                                                                                   
      write (*,*) 'Sub-Inter Common Model017 Horizontal'
      write (*,*) 'attenuation model is not defined for a '                                                                         
      write (*,*) ' spectral period of: '                                                                                           
      write (*,'(a10,f10.5)') ' Period = ',specT                                                                                    
      write (*,*) 'This spectral period is outside the defined'                                                                     
      write (*,*) 'period range in the code or beyond the range'                                                                    
      write (*,*) 'of spectral periods for interpolation.'                                                                          
      write (*,*) 'Please check the input file.'                                                                                    
      write (*,*)                                                                                                                   
      stop 99                                                                                                                       
                                                                                                                                    
C Interpolate the coefficients for the requested spectral period.                                                                   
 1020 call S24_interp (period(count1),period(count2),a1(count1),a1(count2),                                                         
     +                 specT, a1T  ,iflag)                                                                                          
      call S24_interp (period(count1),period(count2),a2(count1),a2(count2),                                                         
     +                 specT, a2T  ,iflag)                                                                                          
      call S24_interp (period(count1),period(count2),a3(count1),a3(count2),                                                         
     +                 specT, a3T  ,iflag)                                                                                          
      call S24_interp (period(count1),period(count2),a4(count1),a4(count2),                                                         
     +                 specT, a4T  ,iflag)                                                                                          
      call S24_interp (period(count1),period(count2),a5(count1),a5(count2),                                                         
     +                 specT, a5T  ,iflag)                                                                                          
      call S24_interp (period(count1),period(count2),a6(count1),a6(count2),                                                         
     +                 specT, a6T  ,iflag)                                                                                          
      call S24_interp (period(count1),period(count2),a11(count1),a11(count2),                                                       
     +                 specT, a11T ,iflag)                                                                                          
      call S24_interp (period(count1),period(count2),dsi(count1),dsi(count2),                                                       
     +                 specT, dsiT ,iflag)                                                                                          
      call S24_interp (period(count1),period(count2),Mref(count1),Mref(count2),                                                     
     +                 specT, MrefT,iflag)                                                                                          
                                                                                                                                    
 1011 period1 = specT                                                                                                               
                                                                                                                                    
C     Set Constant Terms                                                                                                            
                                                                                                                                    
C     Compute the ground motion for the given spectral period.                                                                      
      if (M .le. MrefT) then 
         fmag = a4T*(M-MrefT)                                                   
      elseif(M .gt. MrefT) then                                                                                                                            
         fmag = a5T*(M-MrefT)                                                     
      endif                                                                                                                         
         lnY = a1T + ( a2T + a3T *(M-7.8))*alog(Rrup + 10.0*exp(0.4*(M-6.0)))                                            
     1         + fmag  + a11T*min(Ztor,dsiT) + a6T*Rrup             
                                                                                                                                 
      sigma = 0.65                                                                                                                  
                                                                                                                                    
c     Convert from g to gal                                                                                                         
      lnY = lnY + 6.89                                                                                                              
                                                                                                                                    
      period2 = period1                                                                                                             
                                                                                                                                    
      return                                                                                                                        
      end


